```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Dibujar un arcoíris en la consola de salida
void drawRainbow() {
    // Parámetros para el arcoíris
    int centerX = 60, centerY = 20, radius = 30;
    int colors[7] = {0,  255, 255, 255, 0, 255, 0}; // RGB para cada segmento
    int numSegments = 7;
    int i;
    int x1 = centerX - radius;
    int y1 = centerY;
    int x2 = centerX + radius;
    int y2 = centerY;

    // Dibujar el arcoíris
    for (i = 0; i <= numSegments; i++) {
        int angle = (i * 360) / numSegments;
        int rad = angle * 3.1415926 / 180;
        int x = centerX + radius * cos(rad);
        int y = centerY + radius * sin(rad);

        // Dibujar la línea de (x1, y1) a (x, y) con el color correcto
        setcolor(colors[i % 7]);
        line(x1, y1, x, y);
    }
}

// Función auxiliar para establecer el color de la consola
void setcolor(int r, int g, int b) {
    // Establecer el color de la consola de salida
    setcolor(r, g, b, 255);
}

// Función auxiliar para dibujar una línea en la consola de salida
void line(int x1, int y1, int x2, int y2) {
    int dx = abs(x2 - x1), dy = abs(y2 - y1);
    int sx = (x1 < x2) ? 1 : -1;
    int sy = (y1 < y2) ? 1 : -1;
    int err = dx - dy, e2;

    while (1) {
        setcolor(0, 0, 0, 255); // Dibujar la línea
        printf(" ");
        if (y1 == y2)
            break;
        e2 = 2 * (err);
        if (e2 > -dy)
            err -= dy, x1++, sx = (x1 < x2) ? 1 : -1;
        if (e2 < dx)
            err += dx, y1++, sy = (y1 < y2) ? 1 : -1;
    }
}

// Función auxiliar para establecer el color de la consola
void setcolor(int r, int g, int b, int a) {
    printf("\033[48;2;%d;%d;%dm", r, g, b, a); // ANSI escape para color
}

int main() {
    srand((unsigned int)time(NULL));
    drawRainbow();
    printf("\nPresiona Enter para salir...");
    getchar();
    return 0;
}
```

**Notas:**
