#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Función para establecer el color de texto
void set_color(int color) {
    printf("\033[1;%dm", 30 + color);
}

// Función para establecer el color de fondo
void set_bg(int color) {
    printf("\033[48;%d;%dm", 10 + color, 10 + color);
}

// Dibuja un arcoíris
void draw_rainbow() {
    // Colores para el arcoíris: Rojo, naranja, amarillo, verde, azul, índigo, violeta
    int colors[] = {0, 1, 2, 3, 4, 5, 6};
    char* names[] = {"red", "orange", "yellow", "green", "blue", "indigo", "violet"};
    int i, r;

    srand(time(NULL));
    for (i = 0; i < 7; i++) {
        set_color(i);      // Establece el color de texto
        set_bg(7 - i);     // Establece el color de fondo (inverso del color de texto)
        printf("%s ", names[i]);
        for (r = 0; r < 80; r++) printf("#");
        printf("\n");
    }
}

int main() {
    draw_rainbow();
    return 0;
}
```

